import {HAClient,websocketURL} from './ha-client.js';
import {BridgeClient,gatewayURL} from './bridge-client.js';
import {compatible,available,adjustable,projectState,serviceFor,matchesDesired,cleanConnection} from './ha-domain.js';
const STORAGE='jm-home-pro-connections-r03';
export class Connections {
 constructor({getDevices,onUpdate=()=>{},onMode=()=>{},onLog=()=>{},storage=globalThis.localStorage,clientOptions={},bridgeOptions={},defaultProvider='ha',confirmationTimeout=12000,coverTimeout=30000}){
  Object.assign(this,{getDevices,onUpdate,onMode,onLog,storage,confirmationTimeout,coverTimeout,clientOptions,bridgeOptions});this.live=false;this.pending=new Set();this.tickets=new Map();this.waiters=new Set();this.lastMessage='Nenhuma central conectada.';
  try{this.provider=storage?.getItem('jm-home-provider-r04')??defaultProvider;}catch{this.provider=defaultProvider;}
  if(!['ha','tuya'].includes(this.provider))this.provider=defaultProvider;
  this.loadConfig();this.api=this.makeAPI();
 }
 get providerName(){return this.provider==='tuya'?'Tuya':'Home Assistant';}
 loadConfig(){this.config=cleanConnection({},this.getDevices());try{this.config=cleanConnection(JSON.parse(this.storage?.getItem(this.provider==='tuya'?'jm-home-tuya-r04':STORAGE)??'{}'),this.getDevices());}catch{}}
 makeAPI(){const events={onStatus:(status,message)=>{this.lastMessage=message;if(status==='offline'){for(const w of this.waiters)w.fail(Error(message));this.waiters.clear();}this.onUpdate();},onState:()=>{for(const w of [...this.waiters])w.check();this.onUpdate();}};return this.provider==='tuya'?new BridgeClient({...this.bridgeOptions,...events}):new HAClient({...this.clientOptions,...events});}
 selectProvider(provider){if(!['ha','tuya'].includes(provider)||provider===this.provider)return;if(this.live||this.pending.size)throw Error('Volte à demonstração antes de trocar a conexão.');this.api.disconnect();this.provider=provider;this.loadConfig();this.api=this.makeAPI();this.lastMessage='Nenhuma central conectada.';try{this.storage?.setItem('jm-home-provider-r04',provider);}catch{}this.onUpdate();}
 persist(){try{this.storage?.setItem(this.provider==='tuya'?'jm-home-tuya-r04':STORAGE,JSON.stringify(cleanConnection(this.config,this.getDevices())));}catch{throw Error('Não foi possível salvar os vínculos neste navegador.');}}
 async connect(address,token){if(this.live)throw Error('Volte à demonstração antes de trocar a central.');if(this.provider==='tuya')gatewayURL(address);else websocketURL(address);if(this.config.address&&new URL(this.config.address).href!==new URL(address).href)this.config.bindings={};this.config.address=new URL(address).href;this.persist();return this.api.connect(address,token);}
 bind(id,entity){if(this.live)throw Error('Volte à demonstração para editar os vínculos.');const d=this.getDevices().find(d=>d.id===id);if(!d)throw Error('Dispositivo não encontrado.');if(entity&&(!compatible(d,this.api.states.get(entity))||Object.entries(this.config.bindings).some(([key,v])=>key!==id&&v===entity)))throw Error('Escolha uma entidade compatível ainda não vinculada.');if(entity)this.config.bindings[id]=entity;else delete this.config.bindings[id];this.persist();this.onUpdate();}
 entity(d){return this.api.states.get(this.config.bindings[d.id]);}
 project(d){return this.api.status==='connected'?projectState(d,this.entity(d)):{...d,online:false,on:false};}
 canAdjust(d){return this.api.status==='connected'&&(d.type!=='ac'||this.api.config.unit_system?.temperature==='°C')&&adjustable(d,this.entity(d));}
 enable(){if(this.provider==='tuya'&&!this.api.controlEnabled)throw Error('Servidor Tuya em leitura. Habilite os comandos no servidor após conferir o cadastro.');if(this.api.status!=='connected')throw Error('Conecte a central primeiro.');if(!this.getDevices().some(d=>compatible(d,this.entity(d))&&available(this.entity(d))))throw Error('Vincule ao menos um dispositivo disponível.');this.live=true;this.onMode(true);this.onLog('Modo real habilitado nesta aba. Rotinas locais e assistente ficam pausados.');this.onUpdate();}
 disable(){if(this.pending.size)throw Error('Aguarde os comandos pendentes antes de voltar à demonstração.');this.live=false;this.onMode(false);this.onUpdate();}
 async refresh(){await this.api.refresh();this.onUpdate();}
 prepare(d,patch){if(!this.live||this.api.status!=='connected')throw Error('Modo real sem conexão. Nenhum comando enviado.');const command=serviceFor(d,this.entity(d),patch,this.api.services,this.api.config);this.api.validate?.(command);return command;}
 async control(id,patch,source='Painel'){
  const d=this.getDevices().find(d=>d.id===id);if(!d)return{ok:false,message:'Dispositivo não encontrado.'};if(this.pending.has(id)&&!patch.stop)return{ok:false,message:'Aguarde o retorno do comando anterior.'};
  let command;try{command=this.prepare(d,patch);}catch(e){return{ok:false,message:e.message};}
  const ticket=(this.tickets.get(id)??0)+1;this.tickets.set(id,ticket);if(patch.stop){for(const w of [...this.waiters])if(w.deviceId===id)w.fail(Error('Movimento substituído por um comando de parada.'));}this.pending.add(id);this.lastMessage=`${d.name}: enviando comando…`;this.onUpdate();const generation=this.api.generation;
  try{
   await this.api.call(command);if(generation!==this.api.generation)throw Error('A conexão mudou durante o comando.');if(this.tickets.get(id)!==ticket)throw Error('Comando substituído pela parada.');
   await this.api.refresh();this.onUpdate();if(this.tickets.get(id)!==ticket)throw Error('Comando substituído pela parada.');
   if(!matchesDesired(d,this.entity(d),patch))await this.waitFor(d,patch,generation);
   const message=`${d.name}: estado confirmado pelo ${this.providerName}.`;this.lastMessage=message;this.onLog(message,source);return{ok:true,message};
  }catch(e){const message=`${d.name}: ${e.message}`;this.lastMessage=message;this.onLog(message,source,'warning');return{ok:false,message};}
  finally{if(this.tickets.get(id)===ticket)this.pending.delete(id);this.onUpdate();}
 }
 waitFor(d,patch,generation){return new Promise((resolve,reject)=>{const done=(error)=>{clearTimeout(timer);this.waiters.delete(w);error?reject(error):resolve();};const w={deviceId:d.id,fail:done,check:()=>{if(generation!==this.api.generation)return done(Error('Conexão interrompida.'));if(matchesDesired(d,this.entity(d),patch))done();}};const timer=setTimeout(()=>done(Error('A central aceitou a ação, mas não confirmou o estado solicitado. Verifique o equipamento.')),d.type==='curtain'?this.coverTimeout:this.confirmationTimeout);this.waiters.add(w);w.check();});}
 async scene(scene){
  if(!scene)return{ok:false,message:'Cena não encontrada.'};if(this.pending.size)return{ok:false,message:'Aguarde os comandos em andamento.'};
  // Valida todos os vínculos e serviços antes de acionar o primeiro equipamento.
  try{for(const a of scene.actions){const d=this.getDevices().find(d=>d.id===a.device);if(!d)throw Error('Dispositivo ausente na cena.');this.prepare(d,a);}}catch(e){return{ok:false,message:`Cena não iniciada: ${e.message}`};}
  let count=0;for(const a of scene.actions){const r=await this.control(a.device,a,`Cena: ${scene.name}`);if(!r.ok)return{ok:false,message:`${scene.name}: interrompida após ${count} ação(ões). ${r.message} As ações anteriores não foram desfeitas.`};count++;}
  return{ok:true,message:`${scene.name}: ${count} estado(s) confirmado(s) pela central.`};
 }
}

export function connectionsPage(c,devices,{E,I,roomName}){
 const connected=c.api.status==='connected',busy=['connecting','syncing'].includes(c.api.status),bound=devices.filter(d=>c.config.bindings[d.id]).length;
 return `<div class="page-heading"><div><p class="eyebrow">DO PAINEL À SUA CASA</p><h1>Conexões reais</h1><p>Conecte sua central, escolha os equipamentos e acompanhe os estados.</p></div><a class="btn secondary" href="${c.provider==='tuya'?'./guia-tuya-whatsapp.html':'./guia-conexao.html'}" target="_blank" rel="noopener">${I('info')} Guia de conexão</a></div>
 <div class="provider-picker" role="group" aria-label="Tipo de conexão"><button class="btn ${c.provider==='tuya'?'primary':'secondary'}" data-act="connection-provider" data-id="tuya" ${c.live?'disabled':''}>Tuya direto</button><button class="btn ${c.provider==='ha'?'primary':'secondary'}" data-act="connection-provider" data-id="ha" ${c.live?'disabled':''}>Home Assistant</button></div>
 <section class="connection-banner ${connected?'ready':''}"><span class="connection-emblem">${I('home')}</span><div><span class="kicker">${c.provider==='tuya'?'TUYA · JM CONNECT':'HOME ASSISTANT'}</span><h2>${connected?(c.live?'Controle real habilitado':'Conectado · somente leitura'):busy?'Conectando…':'Conecte sua casa'}</h2><p role="status">${E(c.lastMessage)}</p></div><span class="pill">${bound} vínculo(s)</span></section>
 <div class="connection-layout"><section class="panel connection-form"><div class="section-heading"><h2>1. Acesse a central</h2>${I('shield')}</div><form data-form="ha-connect" autocomplete="off"><label>${c.provider==='tuya'?'URL do servidor JM CONNECT':'Endereço do Home Assistant'}<input name="address" type="url" placeholder="https://sua-central.exemplo.com" value="${E(c.config.address)}" required maxlength="300" ${connected||busy?'disabled':''}></label><label>${c.provider==='tuya'?'Chave de acesso JM CONNECT':'Token de acesso de longa duração'}<input name="ha-token" type="password" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="Cole somente aqui, nesta sessão" required ${connected||busy?'disabled':''}></label><p class="field-help">${c.provider==='tuya'?'Use JM_ADMIN_TOKEN; nunca informe aqui o segredo Tuya ou o token Meta.':'O token é enviado apenas à central informada.'} Não fica no projeto, no backup nem no armazenamento do painel. Use seu próprio tablet e uma central de confiança.</p><button class="btn primary" type="submit" ${connected||busy?'disabled':''}>${I('plug')} ${busy?'Conectando…':'Conectar e ler entidades'}</button></form><div class="connection-buttons"><button class="btn secondary" data-act="ha-refresh" ${!connected?'disabled':''}>${I('refresh')} Atualizar estados</button><button class="btn secondary" data-act="ha-disconnect" ${!connected&&!busy?'disabled':''}>Desconectar</button></div><div class="notice">${I('info')} Pelo link online, a central precisa oferecer HTTPS/WSS válido. Central HTTP local: use o pacote do painel na sua rede. Veja o guia.</div></section>
 <section class="panel connection-mode"><h2>3. Escolha como operar</h2><p>A conexão começa em leitura. Os comandos só são liberados após a vinculação e sua escolha abaixo.</p><div class="mode-summary"><span class="status-dot ${c.live?'':'off'}"></span><strong>${c.live?'Modo real':'Modo demonstração'}</strong><small>${c.live?'A casa 3D e os cartões usam estados da central.':'Os controles da casa continuam simulados.'}</small></div><button class="btn ${c.live?'secondary':'primary'}" data-act="${c.live?'ha-demo':'ha-enable'}" ${!c.live&&(!connected||!bound)?'disabled':''}>${I(c.live?'cube':'check')}${c.live?'Voltar à demonstração':'Habilitar controle real'}</button><ul class="connection-notes"><li>Equipamento sem vínculo fica indisponível no modo real.</li><li>Sem retorno da central, não há indicação de sucesso.</li><li>Rotinas locais e assistente atuam somente na demonstração. Configure automações reais no Tuya ou no Home Assistant.</li><li>Energia continua sendo uma estimativa, sem medidor integrado.</li></ul><p class="field-help">Desconectar não desliga as cargas nem pausa o WhatsApp configurado no servidor. Use os comandos do equipamento ou da central.</p></section></div>
 <section class="panel binding-panel"><div class="section-heading"><div><span class="kicker">2. ASSOCIE OS EQUIPAMENTOS</span><h2>Dispositivo do painel → entidade real</h2></div><span class="pill subtle">${connected?c.api.states.size+' entidades lidas':'Aguardando conexão'}</span></div><p class="field-help">Cada entidade pode ser vinculada uma vez. Os vínculos ficam neste navegador; tokens não são salvos.</p><div class="bindings">${devices.map(d=>{const entity=c.entity(d),id=c.config.bindings[d.id]??'',options=[...c.api.states.values()].filter(e=>compatible(d,e)).sort((a,b)=>a.entity_id.localeCompare(b.entity_id));return `<div class="binding-row"><span class="binding-device">${I(d.type==='light'?'bulb':d.type==='ac'?'snow':d.type==='curtain'?'curtain':'plug')}<span><strong>${E(d.name)}</strong><small>${E(roomName(d.room))}</small></span></span><label><span class="sr-only">Vínculo de ${E(d.name)}</span><select data-binding="${E(d.id)}" ${!connected||c.live?'disabled':''}><option value="">Sem vínculo</option>${id&&!options.some(e=>e.entity_id===id)?`<option value="${E(id)}" selected>${E(id)} · ausente</option>`:''}${options.map(e=>`<option value="${E(e.entity_id)}" ${e.entity_id===id?'selected':''}>${E(e.attributes?.friendly_name??e.entity_id)} · ${E(e.entity_id)}</option>`).join('')}</select></label><small class="entity-state ${connected&&available(entity)?'good':''}">${connected&&entity?E(entity.state):id?'Não disponível':'Não vinculado'}</small></div>`;}).join('')}</div></section>
 <div class="integration-grid connection-paths"><section class="panel"><h3>${I('code')} ESP32 e MQTT</h3><p>Adicione seus dispositivos à central por ESPHome ou MQTT. Depois vincule as entidades aqui. Firmware, pinos e cargas dependem do seu hardware.</p></section><section class="panel"><h3>${I('plug')} Tuya / Smart Life</h3><p>Vincule a conta na integração Tuya do Home Assistant. O painel controla as entidades compatíveis expostas pela central.</p></section></div>`;
}
